CREATE SCHEMA IF NOT EXISTS "public";
CREATE TYPE "Role" AS ENUM ('ADMIN', 'STAFF');
CREATE TYPE "OrderStatus" AS ENUM ('PENDING', 'CONFIRMED', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'CANCELLED');
CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'STAFF',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"image" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Product" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT NOT NULL,"shortDescription" TEXT,"sku" TEXT NOT NULL,"price" INTEGER NOT NULL,"compareAtPrice" INTEGER,"costPrice" INTEGER,"stock" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"isFeatured" BOOLEAN NOT NULL DEFAULT false,"categoryId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductImage" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"url" TEXT NOT NULL,"alt" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "ProductImage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductVariant" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"name" TEXT NOT NULL,"sku" TEXT NOT NULL,"price" INTEGER,"stock" INTEGER NOT NULL DEFAULT 0,"attributes" JSONB NOT NULL,CONSTRAINT "ProductVariant_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Order" ("id" TEXT NOT NULL,"orderNumber" TEXT NOT NULL,"idempotencyKey" TEXT,"customerName" TEXT NOT NULL,"customerPhone" TEXT NOT NULL,"address" TEXT NOT NULL,"city" TEXT NOT NULL,"landmark" TEXT,"notes" TEXT,"subtotal" INTEGER NOT NULL,"deliveryFee" INTEGER NOT NULL,"discount" INTEGER NOT NULL DEFAULT 0,"total" INTEGER NOT NULL,"status" "OrderStatus" NOT NULL DEFAULT 'PENDING',"whatsappSent" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Order_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"productId" TEXT NOT NULL,"variantId" TEXT,"productNameSnapshot" TEXT NOT NULL,"skuSnapshot" TEXT NOT NULL,"price" INTEGER NOT NULL,"quantity" INTEGER NOT NULL,"variantSnapshot" JSONB,"subtotal" INTEGER NOT NULL,CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BusinessSettings" ("id" TEXT NOT NULL DEFAULT 'default',"businessName" TEXT NOT NULL DEFAULT 'NOVA MART',"logo" TEXT,"whatsappNumber" TEXT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'Rs.',"deliveryFee" INTEGER NOT NULL DEFAULT 250,"minimumOrder" INTEGER NOT NULL DEFAULT 0,"address" TEXT,"phone" TEXT,"email" TEXT,"announcement" TEXT,"primaryColor" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "BusinessSettings_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug"); CREATE INDEX "Category_isActive_idx" ON "Category"("isActive"); CREATE UNIQUE INDEX "Product_slug_key" ON "Product"("slug"); CREATE UNIQUE INDEX "Product_sku_key" ON "Product"("sku"); CREATE INDEX "Product_categoryId_isActive_idx" ON "Product"("categoryId","isActive"); CREATE INDEX "Product_isFeatured_isActive_idx" ON "Product"("isFeatured","isActive"); CREATE INDEX "ProductImage_productId_sortOrder_idx" ON "ProductImage"("productId","sortOrder"); CREATE UNIQUE INDEX "ProductVariant_sku_key" ON "ProductVariant"("sku"); CREATE INDEX "ProductVariant_productId_idx" ON "ProductVariant"("productId"); CREATE UNIQUE INDEX "Order_orderNumber_key" ON "Order"("orderNumber"); CREATE UNIQUE INDEX "Order_idempotencyKey_key" ON "Order"("idempotencyKey"); CREATE INDEX "Order_status_createdAt_idx" ON "Order"("status","createdAt"); CREATE INDEX "Order_customerPhone_idx" ON "Order"("customerPhone"); CREATE INDEX "OrderItem_orderId_idx" ON "OrderItem"("orderId");
ALTER TABLE "Product" ADD CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ProductImage" ADD CONSTRAINT "ProductImage_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ProductVariant" ADD CONSTRAINT "ProductVariant_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
